import React, { useState, useEffect } from 'react'
import CommonSection from '../shared/CommonSection'
import '../styles/tour.css'
import TourCard from './../shared/TourCard'
import SearchBar from './../shared/SearchBar'
import NewsLetter from './../shared/Newsletter'
import { Col, Container, Row } from 'reactstrap'
import useFetch from '../hooks/useFetch'
import {BASE_URL} from '../utils/config'

const PAGE_SIZE = 8

const Tour = () => {
  const { data: tours, error, loading } = useFetch(`${BASE_URL}/tours`)
  const [pageCount, setPageCount] = useState(0)
  const [page, setPage] = useState(0)

  useEffect(() => {
    const pages = Math.ceil(tours.length / PAGE_SIZE)
    setPageCount(pages)
    window.scrollTo(0, 0)
  }, [page, tours])

  return (
    <>
      <CommonSection title={"All Tours"}/>
      <section>
        <Container>
          <Row>
            <SearchBar />
          </Row>
        </Container>
      </section>
      <section className='pt-0'>
        <Container>
          <Row>
            {loading && <Col lg='12'><h4 className='text-center'>loading.................</h4></Col>}
            {error && <Col lg='12'><h4 className='text-center'>{error}</h4></Col>}

            {tours
              ?.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE)
              .map(tour => (
                <Col lg='3' className='mb-4' key={tour._id}>
                  <TourCard tour={tour}/>
                </Col>
              ))}

            <Col lg='12'>
              <div className="pagination d-flex align-items-center justify-content-center mt-4 gap-3">
                {[...Array(pageCount).keys()].map(number => (
                  <span
                    key={number}
                    className={page === number ? "active__page" : ""}
                    onClick={() => setPage(number)}
                  >
                    {number + 1}
                  </span>
                ))}
              </div>
            </Col>
          </Row>
        </Container>
      </section>
      <NewsLetter />
    </>
  )
}

export default Tour
